// Optimized function to pre-calculate the earliest buy date for all symbols from fills
function precomputeEarliestBuyDates(fills) {
    const earliestBuyDates = new Map();
    for (const fill of fills) {
        if (fill.activity_type === 'FILL' && fill.side === 'buy') {
            const normalizedSymbol = getNormalizedSymbol(fill.symbol);
            const fillDate = new Date(fill.transaction_time || fill.filled_at || fill.created_at);

            if (!earliestBuyDates.has(normalizedSymbol) || fillDate < earliestBuyDates.get(normalizedSymbol)) {
                earliestBuyDates.set(normalizedSymbol, fillDate);
            }
        }
    }
    // Convert dates to ISO string format
    for (const [symbol, date] of earliestBuyDates.entries()) {
        earliestBuyDates.set(symbol, date.toISOString().split('T')[0]);
    }
    return earliestBuyDates;
}

// This function processes all fills to build a cost basis and PnL history (FIFO)
function processFillsForPnL(fills) {
    const tradeLog = {}; // Stores { normalizedSymbol: { openLots: [], closedPnL: { order_id: { totalPnL: ..., avgBuyPrice: ..., totalCost: ... } } } }

    // Sort fills by transaction_time ascending to ensure correct FIFO order
    fills.sort((a, b) => {
        const timeA = a.transaction_time ? new Date(a.transaction_time).getTime() : 0;
        const timeB = b.transaction_time ? new Date(b.transaction_time).getTime() : 0;

        // Defensively handle cases where dates might be invalid
        if (isNaN(timeA) && isNaN(timeB)) return 0;
        if (isNaN(timeA)) return 1; // Push invalid dates to the end
        if (isNaN(timeB)) return -1; // Push invalid dates to the end

        return timeA - timeB;
    });

    for (const fill of fills) {
        if (fill.activity_type !== 'FILL') continue; // Only process fills

        const normalizedSymbol = getNormalizedSymbol(fill.symbol);
        if (!tradeLog[normalizedSymbol]) {
            tradeLog[normalizedSymbol] = { openLots: [], closedPnL: {} };
        }

        const price = parseFloat(fill.price);
        const qty = parseFloat(fill.qty);

        if (fill.side === 'buy') {
            tradeLog[normalizedSymbol].openLots.push({ price, qty });
        } else if (fill.side === 'sell') {
            let remainingSellQty = qty;
            let totalCostOfSoldShares = 0;
            const totalRevenueFromSoldShares = price * qty; // Revenue from this sell fill

            // FIFO logic: consume oldest buy lots first
            while (remainingSellQty > 0 && tradeLog[normalizedSymbol].openLots.length > 0) {
                const oldestLot = tradeLog[normalizedSymbol].openLots[0];
                const qtyToSellFromLot = Math.min(remainingSellQty, oldestLot.qty);

                totalCostOfSoldShares += qtyToSellFromLot * oldestLot.price;
                oldestLot.qty -= qtyToSellFromLot;
                remainingSellQty -= qtyToSellFromLot;

                if (oldestLot.qty === 0) {
                    tradeLog[normalizedSymbol].openLots.shift(); // Remove fully consumed lot
                }
            }

            // Calculate PnL for this specific sell fill
            const pnlForFill = totalRevenueFromSoldShares - totalCostOfSoldShares;

            // Aggregate PnL and cost for the entire order (if it has multiple fills)
            if (!tradeLog[normalizedSymbol].closedPnL[fill.order_id]) {
                tradeLog[normalizedSymbol].closedPnL[fill.order_id] = { totalPnL: 0, totalCost: 0, totalQtySold: 0 };
            }
            tradeLog[normalizedSymbol].closedPnL[fill.order_id].totalPnL += pnlForFill;
            tradeLog[normalizedSymbol].closedPnL[fill.order_id].totalCost += totalCostOfSoldShares;
            tradeLog[normalizedSymbol].closedPnL[fill.order_id].totalQtySold += qty;
        }
    }

    // Calculate average buy price for each closed PnL entry
    for (const symbol in tradeLog) {
        for (const orderId in tradeLog[symbol].closedPnL) {
            const closedPnL = tradeLog[symbol].closedPnL[orderId];
            if (closedPnL.totalQtySold > 0) {
                closedPnL.avgBuyPrice = closedPnL.totalCost / closedPnL.totalQtySold;
            } else {
                closedPnL.avgBuyPrice = null;
            }
        }
    }

    return tradeLog;
}

