    } else if (accountSnapshotNodeOutput && accountSnapshotNodeOutput.error) {
        console.error("Node 'Get Account Snapshot for Sheet Update' output contains an error:", accountSnapshotNodeOutput.error);
    }
} catch (e) {
    console.warn("Could not access 'Get Account Snapshot for Sheet Update' node. This may be expected if the node did not run. Proceeding with empty account data.", e.message);
}
console.log(`DEBUG: Found account snapshot: ${Object.keys(allAccountSnapshotData).length > 0}`);

// This block will now orchestrate the data fetching and consolidation.
// It will always use the 'Get All Fills' node to ensure a complete history for PnL calculations.
let allFillsData = [];
try {
    const fillsNodeOutput = $('Get All Fills');
    if (fillsNodeOutput && !(fillsNodeOutput instanceof Error) && !fillsNodeOutput.error) {
        // The 'Get All Fills' node returns account activities. We filter for 'FILL' types.
        allFillsData = fillsNodeOutput.all()
            .map(item => item.json)
            .filter(activity => activity && activity.activity_type === 'FILL');
    } else if (fillsNodeOutput instanceof Error) {
