}
console.log(`DEBUG: Found ${allFillsData.length} fill activities from 'Get All Fills'.`);

let processedPortfolioData = [];
try {
    const portfolioProcessingNodeOutput = $('Portfolio Processing Node'); // Corrected node name here
    if (portfolioProcessingNodeOutput && !(portfolioProcessingNodeOutput instanceof Error) && !portfolioProcessingNodeOutput.error) {
        processedPortfolioData = portfolioProcessingNodeOutput.all()
            .map(item => item.json)
            .filter(data => data && Object.keys(data).length > 0);
    } else if (portfolioProcessingNodeOutput instanceof Error) {
        console.error("Node 'Portfolio Processing Node' returned an Error object:", portfolioProcessingNodeOutput.message);
    } else if (portfolioProcessingNodeOutput && portfolioProcessingNodeOutput.error) {
